/* ENAL OS V1.5: local read-only finance reports and safe CSV export. */
function insightWindow(key=insightPeriod){
 const now=localDate();
 if(key==="7d")return {start:shiftDays(now,-6),end:now,label:"Last 7 days"};
 const [y,m]=now.slice(0,7).split("-").map(Number);
 if(key==="previous"){const d=new Date(y,m-2,1),year=d.getFullYear(),mon=pad(d.getMonth()+1),last=pad(new Date(year,d.getMonth()+1,0).getDate());return {start:year+"-"+mon+"-01",end:year+"-"+mon+"-"+last,label:"Previous month"}}
 return {start:now.slice(0,7)+"-01",end:now,label:"Month to date"};
}
function insightData(){
 const window=insightWindow(),tx=data.transactions.filter(t=>t&&typeof t.date==="string"&&t.date>=window.start&&t.date<=window.end&&["income","expense"].includes(t.type)&&Number.isFinite(Number(t.amount))&&Number(t.amount)>0);
 const total=financeTotals(tx),exp=new Map(),inc=new Map();
 for(const t of tx){const category=String(t.category||"Other").trim()||"Other",target=t.type==="expense"?exp:inc;target.set(category,(target.get(category)||0)+Number(t.amount));}
 const sorted=map=>[...map].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));
 return {window,tx,income:total.income,expense:total.expense,net:total.income-total.expense,expenseGroups:sorted(exp),incomeGroups:sorted(inc)};
}
function insightGroupRows(groups,total){
 const max=groups.length?groups[0][1]:1;
 return groups.length?groups.slice(0,12).map(([name,amount])=>{const pct=total>0?Math.round(amount/total*100):0,width=Math.min(100,Math.max(0,amount/max*100));return '<div class="insight-group"><div class="flex-between"><span class="item-title">'+esc(name)+'</span><strong>'+money(amount)+' <span class="muted small">('+pct+'%)</span></strong></div><div class="insight-track"><div style="width:'+width+'%"></div></div></div>'}).join(""):empty("₱","No records for this period.");
}
function insightsPage(){
 const p=insightData(),positive=p.net>=0;
 const categories=insightGroupRows(p.expenseGroups,p.expense),sources=insightGroupRows(p.incomeGroups,p.income);
 return '<div class="welcome"><div><h2>Financial Insights</h2><p>See where your recorded money went. Based only on entries on this device.</p></div><button class="btn btn-primary" data-act="insight-export">↓ Export CSV</button></div>'
 +'<div class="insight-toolbar" role="group" aria-label="Financial review period">'+[["7d","Last 7 days"],["month","This month"],["previous","Last month"]].map(([k,v])=>'<button class="btn btn-filter btn-small" data-act="insight-period" data-value="'+k+'" aria-pressed="'+(insightPeriod===k)+'">'+v+'</button>').join("")+'</div>'
 +'<p class="small muted">Period: '+esc(shortDate(p.window.start))+" – "+esc(shortDate(p.window.end))+' · '+p.tx.length+' entries</p>'
 +'<div class="stats-grid insight-stats">'+stat("↗",money(p.income),"Recorded income","green")+stat("↘",money(p.expense),"Recorded expenses","red")+stat("≈",money(p.net),"Recorded net",positive?"green":"red")+stat("▤",p.tx.length,"Money records")+'</div>'
 +'<div class="insight-split"><section class="card card-pad"><div class="card-head"><h3>Expense categories</h3></div>'+categories+'</section><section class="card card-pad"><div class="card-head"><h3>Income sources</h3></div>'+sources+'</section></div>'
 +'<section class="card card-pad insight-summary"><h3>Weekly review notes</h3><p>Largest recorded expense: <strong>'+(p.expenseGroups.length?esc(p.expenseGroups[0][0])+" — "+money(p.expenseGroups[0][1]):"None")+'</strong></p><p>Recorded difference: <strong>'+money(p.net)+'</strong> (income minus recorded expenses).</p><p class="small muted">CSV includes individual transactions for the chosen period, including bills already paid and logged. Unpaid scheduled bills and separate manual savings entries are not included. Avoid double counting if another app or payout already deducts costs.</p></section>'
 +'<p class="note">These totals do not represent available cash, complete financial history, or verified bank balances. Records remain on your current device, unless you export them yourself.</p>';
}
function csvCell(input){let v=String(input??"");if(/^[\s]*[=+\-@\t\r]/.test(v))v="\u0027"+v;return "\""+v.replace(/\"/g,"\"\"")+"\""}
function exportInsightCSV(){
 const p=insightData(),table=[["Date","Type","Category","Amount PHP","Note","Bill payment"]];
 for(const t of [...p.tx].sort((a,b)=>String(a.date).localeCompare(String(b.date))))table.push([t.date,t.type,t.category||"Other",Number(t.amount).toFixed(2),t.note||"",t.billPaymentId?"Yes":"No"]);
 const csv="\uFEFF"+table.map(row=>row.map(csvCell).join(",")).join("\r\n")+"\r\n";
 const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="ENAL-OS-Finances-"+insightPeriod+"-"+localDate()+".csv";document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);notify("CSV export created. Keep it private.");
}
function insightsMiniPanel(){const p=insightData();return '<section class="card upcoming-strip" id="insights-mini"><div><strong>▤ Money review — this month</strong><p>'+money(financeTotals().income-financeTotals().expense)+' recorded net. Actual available cash may differ.</p></div><button class="btn btn-small" data-act="nav" data-page="insights">Open insights →</button></section>'}
/* ENAL OS V1.7 — today-first delivery finances without changing data schema. */
function dailyMoneyPanel(){
 const today=localDate();
 const recorded=data.transactions.filter(t=>t&&t.date===today&&(t.type==="income"||t.type==="expense")&&Number.isFinite(Number(t.amount))&&Number(t.amount)>0);
 const total=financeTotals(recorded),grab=grabDaySummary(today),running=grab.fuel+grab.other;
 const target=Math.max(0,Number(data.settings.dailyGrabGoal)||0);
 const remaining=target?Math.max(0,target-grab.net):null;
 const pct=target?Math.max(0,Math.min(100,Math.round(Math.max(0,grab.net)/target*100))):0;
 return '<section class="card card-pad daily-money" id="daily-money"><div class="daily-money-head"><div><span class="eyebrow">TODAY · '+esc(shortDate(today))+'</span><h3>Daily Money Summary</h3><p class="small muted">Fast recording before or after a delivery shift — only when safely stopped.</p></div><button class="btn btn-small" data-act="nav" data-page="finance">Full finances →</button></div>'
 +'<div class="daily-money-stats">'+
 '<div><span class="eyebrow">GRAB INCOME</span><strong>'+money(grab.gross)+'</strong></div>'+
 '<div><span class="eyebrow">FUEL + GRAB COSTS</span><strong>'+money(running)+'</strong></div>'+
 '<div><span class="eyebrow">RECORDED GRAB NET</span><strong class="'+(grab.net<0?"money-negative":"money-positive")+'">'+money(grab.net)+'</strong></div>'+
 '<div><span class="eyebrow">ALL RECORDED EXPENSES</span><strong>'+money(total.expense)+'</strong></div></div>'
 +'<div class="daily-money-goal"><div class="flex-between"><span class="small">Grab daily net target</span><button class="btn btn-small btn-ghost" data-act="edit-grab-goal">'+(target?money(target):"Set target") +' ✎</button></div>'+
 (target?'<div class="meter"><div style="width:'+pct+'%"></div></div><p class="small muted">'+money(remaining)+' remaining according to logged income and costs</p>':'<p class="small muted">Set a daily net target to see your progress.</p>')+'</div>'
 +'<div class="daily-money-actions"><button class="btn btn-primary" data-act="grab-income">＋ Grab income</button><button class="btn" data-act="grab-fuel">＋ Fuel</button><button class="btn" data-act="grab-cost">＋ Grab cost</button><button class="btn" data-act="new-transaction">＋ Other record</button></div>'
 +'<p class="small muted daily-money-note">'+recorded.length+' total money record(s) today, across all categories. Grab net is not available cash. Generic Fuel counts as Grab fuel; expenses should not be logged twice if already deducted from payouts. No automatic account connection.</p></section>';
}
/* ENAL OS V2.0 editable daily routines; local data only. */
function routineToday(){
 const day=localDate(),list=data.routines.filter(r=>r.active!==false),doneIds=new Set(data.routineChecks.filter(x=>x.date===day).map(x=>x.routineId));
 list.sort((a,b)=>String(a.time||"99:99").localeCompare(String(b.time||"99:99"))||String(a.title||"").localeCompare(String(b.title||"")));
 return {day,list,doneIds,done:list.filter(x=>doneIds.has(x.id)).length};
}
function routinePanel(){
 const r=routineToday(),tasks=data.tasks.filter(t=>t.due===r.day),finished=tasks.filter(t=>t.status==="done").length;
 const rows=r.list.map(item=>{const done=r.doneIds.has(item.id);return '<div class="routine-item"><button type="button" class="routine-check '+(done?"routine-checked":"")+'" data-act="routine-toggle" data-id="'+esc(item.id)+'" aria-label="'+(done?"Undo completed ":"Complete ")+esc(item.title)+'" aria-pressed="'+done+'">'+(done?"✓":"○")+'</button><div class="routine-info"><strong class="'+(done?"completed":"")+'">'+esc(item.title)+'</strong><span>'+(item.time?esc(item.time)+" · ":"")+esc(item.category||"Personal")+'</span></div><button class="btn btn-small" data-act="routine-edit" data-id="'+esc(item.id)+'" aria-label="Edit routine">Edit</button></div>'}).join("");
 return '<section class="card routine-plan" id="routine-plan"><div class="routine-header"><div><span class="eyebrow">YOUR DAILY SYSTEM</span><h3>Daily Routine & Focus</h3><p class="small muted">'+esc(shortDate(r.day))+' · Your personal checklist</p></div><button class="btn btn-primary btn-small" data-act="routine-new">＋ Routine</button></div><div class="routine-stats"><div><span class="eyebrow">ROUTINES DONE</span><strong>'+r.done+" / "+r.list.length+'</strong></div><div><span class="eyebrow">TODAY TASKS DONE</span><strong>'+finished+" / "+tasks.length+'</strong></div><div><span class="eyebrow">GRAB NET LOGGED</span><strong>'+money(grabDaySummary(r.day).net)+'</strong></div></div><div class="meter" style="margin-bottom:12px"><div style="width:'+(r.list.length?Math.round(r.done/r.list.length*100):0)+'%"></div></div><div class="routine-list">'+(rows||'<p class="small muted">No routines yet. Create habits such as prayer, exercise, planning, or a money review—your choice.</p>')+'</div><div class="routine-actions"><button class="btn btn-small" data-act="nav" data-page="tasks">Today’s tasks →</button><button class="btn btn-small" data-act="grab-income">＋ Grab income</button></div><p class="small muted routine-note">Check-offs are daily. Completion history stays in local backups. No alarms or background notifications.</p></section>';
}
function routineForm(entry){
 const r=entry||{title:"",time:"",category:"Personal",active:true};
 modal(entry?"Edit daily routine":"Add daily routine",'<form id="entity-form" data-entity="routine" data-id="'+esc(r.id||"")+'"><div class="input-group"><label class="input-label">Routine name *</label><input class="field" name="title" required maxlength="100" placeholder="e.g. Prayer and plan the day" value="'+esc(r.title)+'"></div><div class="form-grid"><div class="input-group"><label class="input-label">Preferred time (optional)</label><input class="field" type="time" name="time" value="'+esc(r.time||"")+'"></div><div class="input-group"><label class="input-label">Category</label><select class="field" name="category">'+["Personal","Health","Grab","Finance","Project","Other"].map(v=>option(v,v,r.category)).join("")+'</select></div></div><div class="input-group"><label class="input-label">Status</label><select class="field" name="active">'+option("yes","Active",r.active===false?"no":"yes")+option("no","Paused",r.active===false?"no":"yes")+'</select></div><p class="small muted">You can pause a routine without losing past check-offs.</p>'+(entry?'<button class="btn btn-danger btn-small" type="button" data-act="routine-delete" data-id="'+esc(entry.id)+'">Delete routine</button>':"")+footer(entry?"Update routine":"Add routine")+'</form>');
}
function routineToggle(rid){
 if(storageIssue)return notify("Stored data needs recovery; open Settings.");
 const entry=data.routines.find(x=>x.id===rid&&x.active!==false);if(!entry)return;
 const day=localDate(),index=data.routineChecks.findIndex(x=>x.routineId===rid&&x.date===day);
 const previous=index>=0?data.routineChecks[index]:null;
 if(index>=0)data.routineChecks.splice(index,1);else data.routineChecks.push({id:id(),routineId:rid,date:day,completedAt:new Date().toISOString()});
 if(!save()){if(previous)data.routineChecks.push(previous);else data.routineChecks=data.routineChecks.filter(x=>!(x.routineId===rid&&x.date===day));return}
 render();
}
/* ENAL OS V2.1 — weekly read-only review */
function weeklySummary(){
 const end=localDate(),start=shiftDays(end,-6);
 const logs=new Set(data.routineChecks.filter(x=>typeof x.date==="string"&&x.date>=start&&x.date<=end).map(x=>x.date+"|"+x.routineId));
 const tasks=data.tasks.filter(t=>{if(t.status!=="done"||!t.completedAt)return false;const time=new Date(t.completedAt);return !isNaN(time)&&localDate(time)>=start&&localDate(time)<=end});
 const days=Array.from({length:7},(_,i)=>{const date=shiftDays(start,i),g=grabDaySummary(date),checkins=[...logs].filter(x=>x.startsWith(date+"|")).length,done=tasks.filter(t=>localDate(new Date(t.completedAt))===date).length;return {date,checkins,done,net:g.net,gross:g.gross,costs:g.fuel+g.other};});
 return {start,end,days,routines:days.reduce((a,d)=>a+d.checkins,0),tasks:tasks.length,net:days.reduce((a,d)=>a+d.net,0),gross:days.reduce((a,d)=>a+d.gross,0),costs:days.reduce((a,d)=>a+d.costs,0)};
}
function weeklyMiniPanel(){const w=weeklySummary();return '<section class="card upcoming-strip weekly-mini" id="weekly-mini"><div><strong>◷ Last 7 days — quick review</strong><p>'+w.routines+' routine check-offs · '+w.tasks+' tasks completed · '+money(w.net)+' recorded Grab net</p></div><button class="btn btn-small" data-act="nav" data-page="weekly">Open weekly review →</button></section>'}
function weeklyPage(){
 const w=weeklySummary(),max=Math.max(1,...w.days.map(d=>d.checkins));
 const bars=w.days.map(d=>'<div class="weekly-day"><div class="weekly-bar-track"><div class="weekly-bar" style="height:'+(d.checkins?Math.max(8,d.checkins/max*100):0)+'%"></div></div><span>'+esc(parseDate(d.date).toLocaleDateString("en-PH",{weekday:"short"}))+'</span><strong>'+d.checkins+'</strong></div>').join("");
 const rows=w.days.slice().reverse().map(d=>'<tr><td>'+esc(shortDate(d.date))+'</td><td>'+d.checkins+'</td><td>'+d.done+'</td><td class="'+(d.net<0?"money-negative":"money-positive")+'">'+money(d.net)+'</td></tr>').join("");
 return '<div class="welcome"><div><h2>Weekly Productivity Review</h2><p>Last seven days of your recorded routines, tasks, and Grab earnings.</p></div><button class="btn" data-act="nav" data-page="dashboard">Back to dashboard</button></div><p class="small muted">'+esc(shortDate(w.start))+" – "+esc(shortDate(w.end))+'</p>'
 +'<div class="stats-grid weekly-metrics" id="weekly-metrics">'+stat("◎",w.routines,"Routine check-offs")+stat("☑",w.tasks,"Tasks completed")+stat("₱",money(w.net),"Recorded Grab net",w.net<0?"red":"green")+stat("◷",w.days.filter(d=>d.checkins>0).length+"/7","Days with check-offs")+'</div>'
 +'<div class="weekly-columns"><section class="card card-pad" id="weekly-chart"><div class="card-head"><h3>Routine activity</h3></div><div class="weekly-bars" aria-label="Routine check-offs by day">'+bars+'</div><p class="small muted">Saved check-offs per day, not a completion percentage.</p></section><section class="card card-pad"><div class="card-head"><h3>Grab breakdown</h3></div><div class="weekly-money"><div><span>Gross logged</span><strong>'+money(w.gross)+'</strong></div><div><span>Logged operating costs</span><strong>'+money(w.costs)+'</strong></div><div><span>Net recorded</span><strong>'+money(w.net)+'</strong></div></div><button class="btn btn-small" data-act="nav" data-page="finance">Finances →</button></section></div>'
 +'<section class="card card-pad weekly-detail"><h3>Daily breakdown</h3><div class="weekly-table-wrap"><table><thead><tr><th>Date</th><th>Routine checks</th><th>Tasks done</th><th>Grab net</th></tr></thead><tbody>'+rows+'</tbody></table></div></section>'
 +'<p class="note">Read-only summary of locally recorded data. Older tasks without a completion timestamp are excluded. Editing or deleting routines can affect historic counts. Grab net is not a bank balance. No cloud sync or push reminders.</p>';
}
function taskProgress(){const today=localDate();const todayTasks=data.tasks.filter(t=>t.due===today);const done=todayTasks.filter(t=>t.status==='done').length;return {done,total:todayTasks.length,pct:todayTasks.length?Math.round(done*100/todayTasks.length):0}}
function projectProgress(){const all=data.projectItems.length,done=data.projectItems.filter(p=>p.status==='done').length;return {all,done,pct:all?Math.round(done/all*100):0}}
function cleanText(s){return esc(s).replace(/\n/g,'<br>')}
function setPage(p){if(!NAV.some(([key])=>key===p))return;page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'instant'});}
function renderNav(){
 const sidebar=NAV.map(([key,icon,label])=>`<button class="nav-link ${page===key?"active":""}" data-act="nav" data-page="${key}" ${page===key?'aria-current="page"':""}><span class="nav-icon">${icon}</span>${label}</button>`).join("");
 const mobile=[["dashboard","⌂","Home"],["tasks","☑","Tasks"],["finance","₱","Money"],["calendar","▦","Calendar"],["more","☰","More"]];
 const isOther=!mobile.some(([key])=>key===page);
 const bottom=mobile.map(([key,icon,label])=>{const active=key==="more"?isOther:page===key;return `<button type="button" class="mobile-nav-item ${active?"active":""}" data-act="${key==="more"?"more":"nav"}" ${key==="more"?"":'data-page="'+key+'"'} aria-label="${label}" ${active?'aria-current="page"':""}><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></button>`}).join("");
 $("#side-nav").innerHTML=sidebar;
 $("#bottom-nav").innerHTML=bottom;
}
function render(){renderNav();$('#page-title').textContent=NAV.find(x=>x[0]===page)[2];$('#today-date').textContent=longDate(localDate());$('#page').innerHTML=({dashboard:dashboardPage,tasks:tasksPage,finance:financePage,insights:insightsPage,weekly:weeklyPage,savings:savingsPage,ideas:ideasPage,velora:veloraPage,calendar:calendarPage,settings:settingsPage})[page]();renderSaveStatus();}
const stat=(icon,value,label,tone='')=>`<article class="card stat ${tone}"><div class="stat-icon">${icon}</div><div class="value">${value}</div><div class="label">${label}</div></article>`;
const empty=(icon,msg)=>`<div class="empty"><span class="empty-emoji">${icon}</span>${msg}</div>`;
function taskRow(t){return `<div class="row-item"><input aria-label="Complete ${esc(t.title)}" class="check" type="checkbox" data-act="toggle-task" data-id="${esc(t.id)}" ${t.status==='done'?'checked':''}><div class="main-info"><div class="item-title ${t.status==='done'?'completed':''}">${esc(t.title)}</div><div class="item-sub">${esc(t.project||'personal')} ${t.repeat&&t.repeat!=='none'?' • ↻ '+esc(t.repeat):''}${t.notes?' • '+esc(t.notes.slice(0,66)):''}</div></div><div class="item-actions">${t.status==='done'?'<span class="pill done">Done</span>':dueTag(t.due)}${t.status!=='done'&&t.priority==='high'?'<span class="pill high">High</span>':''}<button class="btn btn-small" data-act="edit-task" data-id="${esc(t.id)}" aria-label="Edit task">✎</button></div></div>`}
function billRow(b,compact=false){const due=billNextDate(b);return `<div class="row-item"><div class="stat-icon" style="font-size:20px;flex-shrink:0">▣</div><div class="main-info"><div class="item-title">${esc(b.name)}</div><div class="item-sub">${esc(b.cycle==='monthly'?'Monthly':b.cycle==='weekly'?'Every week':`Every ${b.intervalDays} days`)} • ${money(b.amount)} • Due ${esc(shortDate(due))}</div></div><div class="item-actions">${dueTag(due)}${compact?'':`<button class="btn btn-small btn-primary" data-act="pay-bill" data-id="${esc(b.id)}">Pay</button><button class="btn btn-small" data-act="edit-bill" data-id="${esc(b.id)}">✎</button>`}</div></div>`}
function dashboardPage(){const t=taskProgress(),ft=financeTotals(),bill=orderedBills(),open=openTasks().sort((a,b)=>byDate(a.due,b.due)).slice(0,5),p=projectProgress(),over=openTasks().filter(x=>x.due&&x.due<localDate()).length+bill.filter(x=>billNextDate(x)<localDate()).length;return `<div class="welcome"><div><h2>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(data.settings.name||'Boss')} 👋</h2><p>Your daily mission control. Small steps, clear priorities.</p></div><button class="btn" data-act="go-calendar">▦ Calendar</button></div><section class="card focus-card"><div class="focus-heading"><div><span class="eyebrow">TODAY'S FOCUS</span><h3>Your top priorities</h3><p>Start with urgent and high-priority tasks. Mark one done to move forward.</p></div><button class="btn btn-primary btn-small" data-act="new-priority">＋ Priority</button></div><div class="focus-items">${focusTasks().length?focusTasks().map(taskRow).join(''):empty('☑','No urgent tasks right now. Add a top priority for today.')}</div></section>${routinePanel()}${weeklyMiniPanel()}${dailyMoneyPanel()}${saveReviewPanel()}<div class="stats-grid">${stat('☑',`${t.done}/${t.total}`,'Tasks due today')}${stat('↗',money(ft.income),'Income recorded this month','green')}${stat('↘',money(ft.expense),'Expenses recorded this month','red')}${stat('◷',over,'Overdue tasks & bills',over?'amber':'green')}</div><div class="section-head"><h2 class="section-title">Today at a glance</h2></div><div class="cols-2"><section class="card card-pad"><div class="card-head"><h3>☑ Priority checklist</h3><button class="btn btn-ghost" data-act="nav" data-page="tasks">All tasks →</button></div>${open.length?open.map(taskRow).join(''):empty('☑','Your checklist is clear. Add your first task to get started.')}<button class="btn btn-primary" style="margin-top:14px" data-act="new-task">＋ Add task</button></section><div style="display:grid;gap:16px"><section class="card card-pad"><div class="card-head"><h3>₱ Next payments</h3><button class="btn btn-ghost" data-act="nav" data-page="finance">View bills →</button></div>${bill.length?bill.slice(0,3).map(b=>billRow(b,true)).join(''):empty('₱','No bills yet. Add due dates so nothing slips.')}</section><section class="card panel-hero"><h3>◈ Velora game plan</h3><p>${esc(data.strategy.focus||'Define your current focus.')}</p><div class="flex-between"><span class="small">${p.done} of ${p.all} milestones completed</span><strong>${p.pct}%</strong></div><div class="meter" style="margin:10px 0 14px"><div style="width:${p.pct}%"></div></div><button class="btn" data-act="nav" data-page="velora">Open project board →</button></section></div></div><section class="card upcoming-strip"><div><strong>▣ Bills due in next 7 days</strong><p>${weekBillSummary().upcoming.length} projected payments • ${money(weekBillSummary().dueAmount)} expected</p></div><div class="upcoming-end">${weekBillSummary().overdue.length?`<span class="pill overdue">${weekBillSummary().overdue.length} overdue bill(s)</span>`:'<span class="pill done">No overdue bills</span>'}<button class="btn btn-small" data-act="nav" data-page="finance">View payments →</button></div></section>${budgetMiniPanel()}${savingsMiniPanel()}${insightsMiniPanel()}<div class="section-head"><h2 class="section-title">Quick capture</h2></div><div class="quick-grid" style="max-width:620px"><button class="btn" data-act="new-transaction">₱ Record money</button><button class="btn" data-act="new-idea">✦ Capture idea</button><button class="btn" data-act="new-bill">▣ Add bill</button><button class="btn" data-act="new-project">◈ Velora action</button></div><p class="note" style="margin-top:21px">🔒 <strong>Privacy:</strong> This version saves information in this browser only. Export backups regularly under Settings. It does not sync between devices.</p>`}
function tasksPage(){let tasks=[...data.tasks];if(taskFilter==='open')tasks=tasks.filter(x=>x.status!=='done');else if(taskFilter==='today')tasks=tasks.filter(x=>x.due===localDate());else if(taskFilter==='overdue')tasks=tasks.filter(x=>x.status!=='done'&&x.due&&x.due<localDate());else if(taskFilter==='done')tasks=tasks.filter(x=>x.status==='done');tasks.sort((a,b)=>byDate(a.due,b.due));return `<div class="welcome"><div><h2>Ultimate Checklist</h2><p>Plan the day, pick priorities, and track your wins.</p></div><button class="btn btn-primary" data-act="new-task">＋ New task</button></div><div class="toolbar"><input class="field" id="task-search" type="search" placeholder="Search tasks..." aria-label="Search tasks"><div class="section-actions">${[['open','Open'],['today','Today'],['overdue','Overdue'],['done','Done'],['all','All']].map(([k,v])=>`<button class="btn btn-filter btn-small" data-act="task-filter" data-value="${k}" aria-pressed="${taskFilter===k}">${v}</button>`).join('')}</div></div><div class="card list-card" id="task-results">${tasks.length?tasks.map(taskRow).join(''):empty('☑','Nothing in this view. Add a task or try another filter.')}</div><p class="note" style="margin-top:15px">↻ Repeating tasks automatically generate the next checklist item when you mark one complete.</p>`}
function financePage(){const ft=financeTotals(),net=ft.income-ft.expense,goal=Math.max(0,Number(data.settings.monthlyGoal)||0),bills=orderedBills(),payments=[...data.billPayments].sort((a,b)=>byDate(b.date,a.date)).slice(0,5);let tx=[...data.transactions].sort((a,b)=>byDate(b.date,a.date));if(transactionFilter==='month')tx=tx.filter(x=>monthKey(x.date)===monthKey(localDate()));else if(transactionFilter==='income'||transactionFilter==='expense')tx=tx.filter(x=>x.type===transactionFilter);return `<div class="welcome"><div><h2>Finances & Bills</h2><p>Track actual cash flow, recurring due dates, and your target.</p></div><button class="btn btn-primary" data-act="new-transaction">＋ Add record</button></div><div class="stats-grid">${stat('↗',money(ft.income),'Income • this month','green')}${stat('↘',money(ft.expense),'Expenses • this month','red')}${stat('≈',money(net),'Recorded net • this month',net<0?'red':'green')}${stat('▣',bills.length,'Active recurring bills')}</div><section class="card card-pad" style="margin-top:18px"><div class="flex-between"><h3 style="margin:0;font-size:16px">Monthly income target</h3><button class="btn btn-small" data-act="edit-goal">✎ Set target</button></div><div class="flex-between" style="margin:12px 0 9px"><strong>${money(ft.income)} <span class="muted small">of ${goal?money(goal):'no target set'}</span></strong><span class="pill">${goal?Math.min(100,Math.round(ft.income/goal*100))+'%':'—'}</span></div><div class="meter"><div style="width:${goal?Math.min(100,ft.income/goal*100):0}%"></div></div>${goal?`<div class="small muted" style="margin-top:9px">${money(Math.max(0,goal-ft.income))} remaining to target</div>`:''}</section>${grabFinancePanel()}${smartBudgetPanel()}${savingsMiniPanel()}<section class="week-finance" aria-label="Upcoming bills overview"><div><span class="eyebrow">NEXT 7 DAYS</span><strong>${money(weekBillSummary().dueAmount)}</strong><span class="small muted">${weekBillSummary().upcoming.length} projected payment(s)</span></div><div><span class="eyebrow">PAST DUE</span><strong class="${weekBillSummary().overdue.length?'money-negative':''}">${money(weekBillSummary().overdueAmount)}</strong><span class="small muted">${weekBillSummary().overdue.length} overdue bill(s)</span></div><p class="small muted">Forecast uses your saved bill schedules, not confirmed bank balances or upcoming income.</p></section><div class="finance-split" style="margin-top:18px"><section class="card card-pad"><div class="card-head"><h3>▣ Bills & due dates</h3><button class="btn btn-primary btn-small" data-act="new-bill">＋ Add bill</button></div>${bills.length?bills.map(billRow).join(''):empty('▣','Add motorcycle, feeds, electric, phone, Wi-Fi, or any recurring bill.')}</section><section class="card card-pad"><div class="card-head"><h3>Recent money records</h3><select class="select-chip" id="transaction-filter" aria-label="Filter records"><option value="month" ${transactionFilter==='month'?'selected':''}>This month</option><option value="all" ${transactionFilter==='all'?'selected':''}>All time</option><option value="income" ${transactionFilter==='income'?'selected':''}>Income</option><option value="expense" ${transactionFilter==='expense'?'selected':''}>Expenses</option></select></div>${tx.length?tx.slice(0,35).map(t=>`<div class="row-item"><div class="main-info"><div class="item-title">${esc(t.category||'Other')}${t.note?' • '+esc(t.note.slice(0,60)):''}</div><div class="item-sub">${esc(shortDate(t.date))}${t.billPaymentId?' • Bill payment':''}</div></div><div class="item-actions"><strong class="small money-display ${t.type==='income'?'money-positive':'money-negative'}">${t.type==='income'?'+':'−'}${money(t.amount)}</strong>${t.billPaymentId?'':`<button class="btn btn-small" data-act="edit-transaction" data-id="${esc(t.id)}">✎</button>`}</div></div>`).join(''):empty('₱','No money records yet. Start with your first Grab earning or expense.')}</section></div><div class="section-head"><h2 class="section-title">Payment history</h2></div><section class="card list-card">${payments.length?payments.map(p=>`<div class="row-item"><div class="main-info"><div class="item-title">${esc(p.billName||'Bill')} • ${money(p.amount)}</div><div class="item-sub">Paid ${shortDate(p.date)} • Scheduled ${shortDate(p.dueDate)}</div></div><button class="btn btn-small" data-act="undo-bill" data-id="${esc(p.id)}">Undo</button></div>`).join(''):empty('✓','Your paid bills will appear here.')}</section><p class="note warn" style="margin-top:15px"><strong>Financial note:</strong> Recorded net is income minus logged expenses, not your bank or GCash balance. When you tap Pay on a bill, its amount is automatically logged as an expense. Don't add that payment twice.</p>`}
function ideasPage(){const ideas=[...data.ideas].filter(i=>ideaFilter==='all'||i.status===ideaFilter).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));return `<div class="welcome"><div><h2>Idea Vault</h2><p>Capture now, organize later. Turn ideas into real action.</p></div><button class="btn btn-primary" data-act="new-idea">＋ Capture idea</button></div><div class="toolbar">${[['all','All'],['inbox','Inbox'],['planned','Planned'],['actioned','Actioned']].map(([k,v])=>`<button class="btn btn-filter btn-small" data-act="idea-filter" data-value="${k}" aria-pressed="${ideaFilter===k}">${v}</button>`).join('')}</div><div class="idea-grid">${ideas.length?ideas.map(i=>`<section class="card idea-card"><div class="flex-between"><span class="pill ${i.status==='actioned'?'done':''}">${esc(i.status||'inbox')}</span><span class="muted small">${esc(i.category||'General')}</span></div><h3>${esc(i.title)}</h3><p>${esc(i.details||'No details yet.')}</p><div class="foot"><button class="btn btn-small" data-act="edit-idea" data-id="${esc(i.id)}">✎ Edit</button><button class="btn btn-small" data-act="idea-task" data-id="${esc(i.id)}">☑ To task</button></div></section>`).join(''):empty('✦','Your next big idea starts here. Capture anything — Velora, Grab, business, or personal plans.')}</div>`}
function veloraPage(){const p=projectProgress(),items=[...data.projectItems].filter(x=>projectFilter==='all'||x.status===projectFilter).sort((a,b)=>byDate(a.due,b.due));return `<div class="welcome"><div><h2>Velora — strategy & execution</h2><p>A personal roadmap and action list, kept separate from the real project repository.</p></div><button class="btn btn-primary" data-act="new-project">＋ New milestone</button></div><section class="card project-hero"><div class="flex-between"><div><span class="eyebrow" style="color:#bdcbff">AUTOMOTIVE PROJECT</span><h2>One clear next move at a time.</h2></div><strong style="font-size:26px">${p.pct}%</strong></div><p>${p.done} / ${p.all} tracked items completed. This is your personal checklist, not verified Git/GitHub status.</p><div class="meter" style="margin-top:15px"><div style="width:${p.pct}%"></div></div></section><div class="section-head"><h2 class="section-title">Strategic game plan</h2><button class="btn" data-act="edit-strategy">✎ Edit strategy</button></div><div class="strategy-grid">${[['vision','Vision'],['focus','Current focus'],['next','Next move'],['risk','Guardrails / risks']].map(([key,label])=>`<div class="strategy-box"><div class="heading">${label}</div><div class="body">${cleanText(data.strategy[key]||'Not set')}</div></div>`).join('')}</div><section class="card card-pad" style="margin-top:18px"><div class="card-head"><h3>↗ Next Velora actions</h3><span class="pill velora">Manual project tracking</span></div>${veloraNextActions().length?veloraNextActions().map(item=>`<div class="row-item"><div class="main-info"><div class="item-title">${esc(item.title)}</div><div class="item-sub">${item.due?`Target ${esc(shortDate(item.due))}`:'No target date yet'}</div></div><div class="item-actions"><span class="pill ${esc(item.status)}">${esc(item.status)}</span><button class="btn btn-small" data-act="edit-project" data-id="${esc(item.id)}">Edit</button></div></div>`).join(''):empty('◈','No active milestones yet. Add a verified next action before you start work.')}</section><div class="section-head"><h2 class="section-title">Roadmap & milestones</h2></div><div class="toolbar">${[['all','All'],['planned','Planned'],['doing','In progress'],['blocked','Blocked'],['done','Done']].map(([k,v])=>`<button class="btn btn-filter btn-small" data-act="project-filter" data-value="${k}" aria-pressed="${projectFilter===k}">${v}</button>`).join('')}</div><section class="card list-card">${items.length?items.map(p=>`<div class="row-item"><div class="main-info"><div class="item-title">${esc(p.title)}</div><div class="item-sub">${p.due?shortDate(p.due):'No target date'}${p.notes?' • '+esc(p.notes.slice(0,90)):''}</div></div><div class="item-actions"><span class="pill ${esc(p.status)}">${esc(p.status)}</span><button class="btn btn-small" data-act="edit-project" data-id="${esc(p.id)}">✎</button></div></div>`).join(''):empty('◈','Add milestones like validation, automotive UI, release checklist, or deployment planning.')}</section><p class="note" style="margin-top:15px"><strong>Safety rule:</strong> A milestone marked “Done” here is only a personal update. Code reviews, tenant isolation, tests, approvals, and actual deployment must be verified separately in Velora.</p>`}
function calEvents(day){return [...data.tasks.filter(t=>t.due===day).map(t=>({kind:'task',label:t.title,done:t.status==='done'})),...orderedBills().filter(b=>billNextDate(b)===day).map(b=>({kind:'bill',label:`${b.name} • ${money(b.amount)}`})),...data.projectItems.filter(p=>p.due===day).map(p=>({kind:'project',label:`Velora: ${p.title}`,done:p.status==='done'}))]}
function calendarPage(){const [yr,mo]=calMonth.split('-').map(Number),first=new Date(yr,mo-1,1),days=new Date(yr,mo,0).getDate(),offset=(first.getDay()+6)%7;const cells=[];for(let i=0;i<offset;i++)cells.push('<div class="cal-day blank"></div>');for(let d=1;d<=days;d++){const date=`${yr}-${pad(mo)}-${pad(d)}`,e=calEvents(date);cells.push(`<button class="cal-day ${date===localDate()?'today':''} ${selectedCalDate===date?'selected':''}" data-act="cal-day" data-date="${date}" aria-label="${shortDate(date)} ${e.length} items">${d}<div class="dots">${e.slice(0,4).map(x=>`<span class="dot ${x.kind==='bill'?'bills':''}"></span>`).join('')}</div></button>`)}const ev=calEvents(selectedCalDate);return `<div class="welcome"><div><h2>Calendar & deadlines</h2><p>See tasks, payments, and Velora milestones together.</p></div><button class="btn btn-primary" data-act="new-task">＋ Plan task</button></div><div class="calendar-wrap"><section class="card calendar-card"><div class="calendar-header"><button class="btn btn-small" data-act="cal-prev" aria-label="Previous month">←</button><strong>${first.toLocaleDateString('en-PH',{month:'long',year:'numeric'})}</strong><button class="btn btn-small" data-act="cal-next" aria-label="Next month">→</button></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="cal-weekday">${x}</div>`).join('')}${cells.join('')}</div></section><section class="card card-pad"><div class="card-head"><h3>${shortDate(selectedCalDate)}</h3><button class="btn btn-small" data-act="cal-today">Today</button></div>${ev.length?ev.map(x=>`<div class="row-item"><span class="pill ${x.kind==='bill'?'soon':x.done?'done':'velora'}">${esc(x.kind)}</span><div class="item-title">${esc(x.label)}</div></div>`).join(''):empty('▦','No scheduled items on this date.')}</section></div><p class="note" style="margin-top:15px">Reminders in version 1 appear inside the dashboard and calendar. Background push notifications and phone alarms are not yet supported.</p>`}
function settingsPage(){return `<div class="welcome"><div><h2>Settings & data</h2><p>Customize ENAL OS and keep a copy of your information.</p></div></div><div class="settings-grid">${backupStatusPanel()}<section class="card settings-card"><h3>◉ Profile</h3><p>How should the dashboard greet you?</p><form id="profile-form"><div class="input-group"><label class="input-label" for="display-name">Display name</label><input class="field" id="display-name" name="name" maxlength="50" required value="${esc(data.settings.name||'Boss')}"></div><div class="input-group"><label class="input-label" for="monthly-goal">Monthly income goal (₱)</label><input class="field" id="monthly-goal" name="monthlyGoal" type="number" min="0" step="0.01" value="${Number(data.settings.monthlyGoal)||0}"></div><div class="input-group"><label class="input-label" for="daily-grab-goal">Daily Grab net target (PHP)</label><input class="field" id="daily-grab-goal" name="dailyGrabGoal" type="number" min="0" max="10000000" step="0.01" value="${Number(data.settings.dailyGrabGoal)||0}"></div><button class="btn btn-primary" type="submit">Save settings</button></form></section><section class="card settings-card"><h3>⇩ Backup & restore</h3><p>Your data is saved only on this browser/device. Export JSON to a secure location, especially before clearing app storage or changing phones. A local recovery snapshot alone is not an external backup. ENAL OS records when a backup download is requested, but cannot verify you kept the file.</p><div class="section-actions"><button class="btn btn-primary" data-act="export">↓ Export backup</button><button class="btn" data-act="import">↑ Restore backup</button></div><input id="backup-import" type="file" accept=".json,application/json" style="display:none"></section><section class="card settings-card"><h3>🔒 Privacy & storage</h3><p>No account and no cloud sync. GitHub Pages hosts the app code, but your entries remain stored locally on the device in the browser. This is not encrypted storage; use a device screen lock.</p><p>Offline loading works after the app has been opened on a secure website and the app files have been cached.</p></section><section class="card settings-card"><h3>⚠ Reset workspace</h3><p>Erase all tasks, income/expenses, bills, savings goals, ideas, and milestones from this browser. Export a backup first; a local recovery copy is kept if storage allows.</p><button class="btn btn-danger" data-act="reset">Delete local data</button></section></div>`}
function modal(title,content){$('#dialog-root').innerHTML=`<div class="dialog-overlay" data-act="overlay"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="dialog-close" type="button" data-act="close" aria-label="Close dialog">✕</button></div><div class="dialog-body">${content}</div></div></div>`;setTimeout(()=>$('#dialog-root .field')?.focus(),30)}
const footer=(button='Save')=>`<div class="dialog-foot"><button class="btn" type="button" data-act="close">Cancel</button><button class="btn btn-primary" type="submit">${esc(button)}</button></div>`;
const option=(v,label,selected)=>`<option value="${esc(v)}" ${String(selected)===String(v)?'selected':''}>${esc(label)}</option>`;
function taskForm(t){t=t||{title:'',notes:'',due:localDate(),priority:'medium',project:'personal',repeat:'none'};modal(t.id?'Edit task':'New checklist task',`<form id="entity-form" data-entity="task" data-id="${esc(t.id||'')}"><div class="input-group"><label class="input-label">Task title *</label><input class="field" name="title" required maxlength="140" placeholder="e.g. Review Velora roadmap" value="${esc(t.title)}"></div><div class="form-grid"><div class="input-group"><label class="input-label">Due date</label><input class="field" name="due" type="date" value="${esc(t.due||'')}"></div><div class="input-group"><label class="input-label">Priority</label><select class="field" name="priority">${[['high','High'],['medium','Medium'],['low','Low']].map(x=>option(...x,t.priority)).join('')}</select></div><div class="input-group"><label class="input-label">Category</label><select class="field" name="project">${[['personal','Personal'],['grab','Grab'],['velora','Velora'],['finance','Finance'],['other','Other']].map(x=>option(...x,t.project)).join('')}</select></div><div class="input-group"><label class="input-label">Repeats</label><select class="field" name="repeat">${[['none','Does not repeat'],['daily','Daily'],['weekly','Weekly'],['monthly','Monthly']].map(x=>option(...x,t.repeat)).join('')}</select></div><div class="input-group full"><label class="input-label">Notes (optional)</label><textarea class="field" name="notes" maxlength="2000" placeholder="Extra context">${esc(t.notes)}</textarea></div></div>${t.id?`<button class="btn btn-danger btn-small" type="button" data-act="delete-task" data-id="${esc(t.id)}">Delete task</button>`:''}${footer()}</form>`)}
function transactionForm(t){t=t||{type:'income',amount:'',date:localDate(),category:'Grab',note:''};modal(t.id?'Edit money record':'Record income or expense',`<form id="entity-form" data-entity="transaction" data-id="${esc(t.id||'')}"><div class="form-grid"><div class="input-group"><label class="input-label">Type</label><select class="field" name="type">${[['income','Income (+)'],['expense','Expense (−)']].map(x=>option(...x,t.type)).join('')}</select></div><div class="input-group"><label class="input-label">Amount in ₱ *</label><input class="field" type="number" name="amount" required min="0.01" step="0.01" placeholder="1500" value="${esc(t.amount)}"></div><div class="input-group"><label class="input-label">Date</label><input class="field" type="date" name="date" required value="${esc(t.date)}"></div><div class="input-group"><label class="input-label">Category</label><select class="field" name="category">${['Grab','BYD','Other income','Fuel','Grab Fuel','Grab expense','Food','Pigs Feed','Motor','Bills','Load','Personal','Velora','Other'].map(x=>option(x,x,t.category)).join('')}</select></div><div class="input-group full"><label class="input-label">Notes (optional)</label><textarea class="field" name="note" maxlength="500" placeholder="e.g. net Grab earnings; Gixxer fuel">${esc(t.note)}</textarea></div></div>${t.id?`<button type="button" class="btn btn-danger btn-small" data-act="delete-transaction" data-id="${esc(t.id)}">Delete record</button>`:''}${footer()}</form>`)}
function billForm(b){b=b||{name:'',amount:'',nextDue:localDate(),cycle:'monthly',intervalDays:4,category:'Bills',active:true};modal(b.id?'Edit recurring bill':'Add recurring bill',`<form id="entity-form" data-entity="bill" data-id="${esc(b.id||'')}"><div class="form-grid"><div class="input-group full"><label class="input-label">Bill name *</label><input class="field" name="name" maxlength="100" required value="${esc(b.name)}" placeholder="e.g. Motor installment / Pigs feed"></div><div class="input-group"><label class="input-label">Amount in ₱ *</label><input class="field" type="number" name="amount" min="0.01" step="0.01" required value="${esc(b.amount)}"></div><div class="input-group"><label class="input-label">Next scheduled due date *</label><input class="field" type="date" name="nextDue" required value="${esc(b.nextDue)}"></div><div class="input-group"><label class="input-label">Repeats</label><select class="field" name="cycle">${[['monthly','Monthly'],['weekly','Every 7 days'],['interval','Every N days']].map(x=>option(...x,b.cycle)).join('')}</select></div><div class="input-group"><label class="input-label">N days (if applicable)</label><input class="field" type="number" name="intervalDays" min="1" max="365" value="${esc(b.intervalDays||4)}"></div><div class="input-group full"><label class="input-label">Expense category</label><select class="field" name="category">${['Bills','Pigs Feed','Motor','Fuel','Food','Load','Personal','Velora','Other'].map(x=>option(x,x,b.category)).join('')}</select></div></div><p class="small muted">The next due date moves forward only when you record a payment. Overdue scheduled payments stay visible.</p>${b.id?`<button class="btn btn-danger btn-small" type="button" data-act="delete-bill" data-id="${esc(b.id)}">Delete bill</button>`:''}${footer()}</form>`)}
function ideaForm(i){i=i||{title:'',details:'',category:'General',status:'inbox'};modal(i.id?'Edit idea':'Capture an idea',`<form id="entity-form" data-entity="idea" data-id="${esc(i.id||'')}"><div class="input-group"><label class="input-label">Idea title *</label><input class="field" name="title" maxlength="120" required value="${esc(i.title)}" placeholder="e.g. Voice note for Grab trips"></div><div class="form-grid"><div class="input-group"><label class="input-label">Category</label><select class="field" name="category">${['General','Velora','Grab','Business','Personal','Finance','App feature'].map(x=>option(x,x,i.category)).join('')}</select></div><div class="input-group"><label class="input-label">Status</label><select class="field" name="status">${[['inbox','Inbox'],['planned','Planned'],['actioned','Actioned']].map(x=>option(...x,i.status)).join('')}</select></div><div class="input-group full"><label class="input-label">Describe the idea</label><textarea class="field" name="details" maxlength="4000" placeholder="What is the idea? How can it help you?">${esc(i.details)}</textarea></div></div>${i.id?`<button type="button" class="btn btn-danger btn-small" data-act="delete-idea" data-id="${esc(i.id)}">Delete idea</button>`:''}${footer()}</form>`)}
function projectForm(p){p=p||{title:'',due:'',status:'planned',notes:''};modal(p.id?'Edit Velora milestone':'Add Velora milestone',`<form id="entity-form" data-entity="project" data-id="${esc(p.id||'')}"><div class="input-group"><label class="input-label">Milestone / next action *</label><input class="field" name="title" maxlength="150" required value="${esc(p.title)}" placeholder="e.g. Verify Automotive tenant isolation tests"></div><div class="form-grid"><div class="input-group"><label class="input-label">Status</label><select class="field" name="status">${[['planned','Planned'],['doing','In progress'],['blocked','Blocked'],['done','Done']].map(x=>option(...x,p.status)).join('')}</select></div><div class="input-group"><label class="input-label">Target date</label><input class="field" type="date" name="due" value="${esc(p.due||'')}"></div><div class="input-group full"><label class="input-label">Notes / acceptance evidence</label><textarea class="field" name="notes" maxlength="4000" placeholder="What will count as done? Any blockers?">${esc(p.notes)}</textarea></div></div>${p.id?`<button type="button" class="btn btn-danger btn-small" data-act="delete-project" data-id="${esc(p.id)}">Delete milestone</button>`:''}${footer()}</form>`)}
function strategyForm(){modal('Edit Velora game plan',`<form id="entity-form" data-entity="strategy">${[['vision','Vision / destination'],['focus','Current focus'],['next','Next verified action'],['risk','Guardrails / risks']].map(([k,v])=>`<div class="input-group"><label class="input-label">${v}</label><textarea class="field" name="${k}" maxlength="2000">${esc(data.strategy[k]||'')}</textarea></div>`).join('')}${footer()}</form>`)}
function goalForm(){modal('Set monthly income target',`<form id="entity-form" data-entity="goal"><div class="input-group"><label class="input-label">Monthly income target (₱)</label><input class="field" type="number" min="0" step="0.01" name="monthlyGoal" required value="${Number(data.settings.monthlyGoal)||0}"></div>${footer()}</form>`)}
function quickMenu(){modal('Quick capture',`<div class="quick-grid mobile-quick-grid"><button class="btn btn-primary" data-act="grab-income">＋ Grab income</button><button class="btn" data-act="grab-fuel">＋ Grab fuel</button><button class="btn" data-act="grab-cost">＋ Grab expense</button><button class="btn" data-act="new-transaction">₱ Other money</button><button class="btn" data-act="new-task">☑ New task</button><button class="btn" data-act="new-bill">▣ Recurring bill</button><button class="btn" data-act="new-idea">✦ New idea</button><button class="btn" data-act="new-project">◈ Velora milestone</button><button class="btn" data-act="savings-new">◎ Savings goal</button><button class="btn" data-act="edit-strategy">✎ Game plan</button></div><p class="small muted" style="margin:12px 0 0">Record entries only while parked or stationary. Your information stays on this device.</p>`)}
function moreMenu(){modal('All sections',`<div class="quick-grid">${NAV.map(([p,icon,name])=>`<button class="btn" data-act="nav" data-page="${p}">${icon} ${name}</button>`).join('')}</div><p class="small muted" style="margin:12px 0 0">Use the bottom navigation to return to Home, Tasks, Money, or Calendar.</p>`)}
function close(){if($('#dialog-root'))$('#dialog-root').innerHTML=''}
function checkForm(form){if(!form.reportValidity())return false;return true}
function formSave(form){if(!checkForm(form))return;const fd=new FormData(form),type=form.dataset.entity,editId=form.dataset.id,now=new Date().toISOString(),get=(k)=>String(fd.get(k)||'').trim();if(type==='routine'){const title=get('title'),time=get('time'),category=get('category'),active=get('active')==='yes';if(!title||title.length>100||(time&&!/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(time)))return notify('Invalid routine name or time.');const previous=data.routines.find(x=>x.id===editId);const value={...previous,id:previous?.id||id(),title,category,time,active,createdAt:previous?.createdAt||now};if(previous)Object.assign(previous,value);else data.routines.push(value)}else if(type==='savings-goal'){
 const title=get('title'),target=Number(get('target'));if(!title||!Number.isFinite(target)||target<=0||target>100000000)return notify('Invalid savings goal.');
 const prev=data.savingsGoals.find(g=>g.id===editId);const item={...prev,id:prev?.id||id(),title:title.slice(0,90),target,deadline:get('deadline'),notes:get('notes').slice(0,500),archived:prev?.archived||false,createdAt:prev?.createdAt||now};
 if(prev)Object.assign(prev,item);else data.savingsGoals.push(item);
}else if(type==='savings-entry'){
 const goal=data.savingsGoals.find(g=>g.id===editId),amount=Math.round(Number(get('amount'))*100)/100,movement=form.dataset.move;
 if(!goal||goal.archived||!['deposit','withdraw'].includes(movement)||!Number.isFinite(amount)||amount<=0||amount>100000000)return notify('Invalid savings amount.');
 if(movement==='withdraw'&&amount>savingBalance(goal.id))return notify('Withdrawal exceeds saved amount.');
 if(isNaN(parseDate(get('date'))))return notify('Invalid savings date.');
 data.savingsMoves.push({id:id(),goalId:goal.id,type:movement,amount,date:get('date'),note:get('note').slice(0,180),createdAt:now});
}else if(type==='task'){const prev=data.tasks.find(x=>x.id===editId);const item={...prev,id:prev?.id||id(),title:get('title'),due:get('due'),priority:get('priority'),project:get('project'),repeat:get('repeat'),notes:get('notes'),status:prev?.status||'todo',createdAt:prev?.createdAt||now,editedAt:prev?now:undefined};if(!item.title)return notify('Please enter a task title.');if(prev)Object.assign(prev,item);else data.tasks.push(item)}else if(type==='transaction'){const amount=Number(get('amount'));if(!Number.isFinite(amount)||amount<=0)return notify('Enter an amount above zero.');const prev=data.transactions.find(x=>x.id===editId);const item={...prev,id:prev?.id||id(),type:get('type'),amount,date:get('date'),category:get('category'),note:get('note'),createdAt:prev?.createdAt||now};if(prev)Object.assign(prev,item);else data.transactions.push(item)}else if(type==='bill'){const amount=Number(get('amount'));if(!Number.isFinite(amount)||amount<=0)return notify('Enter a valid bill amount.');const prev=data.bills.find(x=>x.id===editId);const due=get('nextDue'),intervalDays=Number(get('intervalDays'));if(!Number.isFinite(intervalDays)||intervalDays<1||intervalDays>365)return notify('Repeat interval must be 1–365 days.');const item={...prev,id:prev?.id||id(),name:get('name'),amount,nextDue:due,dueDay:prev?.dueDay||Number(due.slice(8)),cycle:get('cycle'),intervalDays,category:get('category'),active:true,createdAt:prev?.createdAt||now};if(prev){if(due!==prev.nextDue)item.dueDay=Number(due.slice(8));Object.assign(prev,item)}else data.bills.push(item)}else if(type==='idea'){const prev=data.ideas.find(x=>x.id===editId);const item={...prev,id:prev?.id||id(),title:get('title'),details:get('details'),category:get('category'),status:get('status'),createdAt:prev?.createdAt||now};if(prev)Object.assign(prev,item);else data.ideas.push(item)}else if(type==='project'){const prev=data.projectItems.find(x=>x.id===editId);const item={...prev,id:prev?.id||id(),title:get('title'),status:get('status'),due:get('due'),notes:get('notes'),createdAt:prev?.createdAt||now};if(prev)Object.assign(prev,item);else data.projectItems.push(item)}else if(type==='strategy'){for(const key of ['vision','focus','next','risk'])data.strategy[key]=get(key)}else if(type==='budget-settings'){const raw=get('planningCash'),n=Number(get('workdaysPerWeek'));if(raw!==''&&(!Number.isFinite(Number(raw))||Number(raw)<0||Number(raw)>100000000))return notify('Enter a valid available budget.');if(!Number.isInteger(n)||n<1||n>7)return notify('Choose workdays from 1 to 7.');data.settings.planningCash=raw===''?null:Number(raw);data.settings.workdaysPerWeek=n}else if(type==='grab-goal'){const v=Number(get('dailyGrabGoal'));if(!Number.isFinite(v)||v<0||v>10000000)return notify('Enter a valid daily target.');data.settings.dailyGrabGoal=v}else if(type==='goal'){data.settings.monthlyGoal=Math.max(0,Number(get('monthlyGoal'))||0)}save();close();render();notify('Saved successfully ✓')}
function advanceTask(s,repeat,repeatDay){const today=localDate();if(!s)s=today;const targetDay=Number(repeatDay||s.slice(8));let next=s;for(let attempts=0;attempts<25000;attempts++){const dt=parseDate(next);if(repeat==='daily')next=shiftDays(next,1);else if(repeat==='weekly')next=shiftDays(next,7);else{const y=dt.getFullYear(),m=dt.getMonth()+1;next=localDate(new Date(y,m,Math.min(targetDay,new Date(y,m+1,0).getDate())))}if(next>today)return next}return shiftDays(today,1)}
function toggleTask(task){
 if(task.status==='done'){
  task.status='todo';delete task.completedAt;
  const auto=data.tasks.find(x=>x.id===task.nextOccurrenceId);
  if(auto&&auto.status==='todo'&&auto.createdFrom===task.id&&!auto.editedAt){data.tasks=data.tasks.filter(x=>x.id!==auto.id);delete task.nextOccurrenceId;}
  save();render();return;
 }
 task.status='done';task.completedAt=new Date().toISOString();
 if(task.repeat&&task.repeat!=='none'&&!data.tasks.some(x=>x.id===task.nextOccurrenceId)){
  const repeatDay=task.repeatDay||Number((task.due||localDate()).slice(8));
  const newDue=advanceTask(task.due,task.repeat,repeatDay);
  const next={...task,id:id(),status:'todo',due:newDue,repeatDay,createdFrom:task.id,nextOccurrenceId:null,completedAt:null,createdAt:new Date().toISOString()};
  task.nextOccurrenceId=next.id;data.tasks.push(next);
 }
 save();render();notify(task.repeat&&task.repeat!=='none'?'Completed! Next recurring task added.':'Task completed ✓')}

function payBill(b){const amount=Number(b.amount)||0,oldDue=billNextDate(b);if(!confirm(`Record payment of ${money(amount)} for "${b.name}" due ${shortDate(oldDue)}?\n\nThis adds an expense record automatically.`))return;const newDue=nextBillDue(b),payId=id(),txnId=id();data.billPayments.push({id:payId,billId:b.id,billName:b.name,amount,date:localDate(),dueDate:oldDue,newDue,txnId});data.transactions.push({id:txnId,billPaymentId:payId,type:'expense',amount,date:localDate(),category:b.category||'Bills',note:`Payment: ${b.name} (due ${oldDue})`,createdAt:new Date().toISOString()});b.nextDue=newDue;save();render();notify(`Paid ${money(amount)}. Next due ${shortDate(newDue)}.`)}
function undoBill(p){const b=data.bills.find(x=>x.id===p.billId),later=data.billPayments.some(x=>x.billId===p.billId&&x.date===p.date&&x.id!==p.id&&x.dueDate>=p.newDue);if(!b||b.nextDue!==p.newDue||later)return notify('Only the latest payment of an unchanged bill can be undone.');if(!confirm(`Undo payment of ${money(p.amount)} for ${p.billName}? The linked expense will also be removed.`))return;b.nextDue=p.dueDate;data.billPayments=data.billPayments.filter(x=>x.id!==p.id);data.transactions=data.transactions.filter(x=>x.id!==p.txnId);save();render();notify('Payment undone.');}
function removeFrom(collection,key,label){if(!confirm(`Delete this ${label}? This cannot be undone unless you exported a backup.`))return;data[collection]=data[collection].filter(x=>x.id!==key);save();close();render();notify(`${label} deleted.`)}
/* ENAL OS V1.6 — backup and local recovery safeguards. */
function snapshotCounts(d){return {tasks:d.tasks.length,money:d.transactions.length,bills:d.bills.length,savingsGoals:d.savingsGoals.length,savingsEntries:d.savingsMoves.length,routines:d.routines.length,ideas:d.ideas.length,velora:d.projectItems.length}}
function downloadText(name,contents,mime){const blob=new Blob([contents],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function getRecovery(){try{const text=localStorage.getItem(RECOVERY_KEY);if(!text)return null;const copy=JSON.parse(text);if(!copy||copy.format!==1)return null;return {...copy,data:normalize(copy.data)}}catch(e){console.warn("Invalid local recovery:",e);return null}}
function saveRecovery(reason){try{if(storageIssue)throw Error("Current storage requires repair.");localStorage.setItem(RECOVERY_KEY,JSON.stringify({format:1,createdAt:new Date().toISOString(),reason,data}));return true}catch(e){notify("Local recovery snapshot failed. Export a JSON backup first.");console.error(e);return false}}
function validateImport(raw){
 if(!raw||typeof raw!=="object"||Array.isArray(raw)||raw.version!==1)throw Error("Not an ENAL OS v1 backup.");
 const next=normalize(raw);
 for(const t of next.transactions){if(!["income","expense"].includes(t.type)||!Number.isFinite(Number(t.amount))||Number(t.amount)<=0)throw Error("Invalid type or amount in a money record.");}
 for(const b of next.bills){if(!Number.isFinite(Number(b.amount))||Number(b.amount)<=0)throw Error("Invalid amount in a recurring bill.");}
 for(const m of next.savingsMoves){if(!["deposit","withdraw"].includes(m.type)||!Number.isFinite(Number(m.amount))||Number(m.amount)<=0)throw Error("Invalid savings entry.");}
 return next;
}
function recoverPrevious(){
 if(storageIssue)return notify("Export damaged raw data and restore from a valid backup first.");
 const recovery=getRecovery();if(!recovery)return notify("No usable local recovery snapshot.");
 if(!confirm("Restore the previous local snapshot from "+new Date(recovery.createdAt).toLocaleString("en-PH")+"? Current records will be replaced. Export a JSON backup first."))return;
 try{
  const replacement=JSON.stringify(recovery.data),newSnapshot=JSON.stringify({format:1,createdAt:new Date().toISOString(),reason:"before recovery",data});
  localStorage.setItem(RECOVERY_KEY,newSnapshot);
  try{localStorage.setItem(KEY,replacement)}catch(e){localStorage.setItem(RECOVERY_KEY,JSON.stringify(recovery));throw e}
  data=recovery.data;writeFailed=false;recordSaveMeta('lastSavedAt');render();notify("Previous local records restored.");
 }catch(e){console.error("Recovery error:",e);notify("Recovery failed; current records were not replaced.")}
}
function downloadDamaged(){let raw;try{raw=localStorage.getItem(KEY)}catch(e){return notify("Cannot read damaged device storage.")}if(raw===null)return notify("No damaged raw data found.");downloadText("ENAL-OS-damaged-"+localDate()+".txt",raw,"text/plain;charset=utf-8");notify("Raw data download requested; keep the file private.")}
function resetWorkspace(){
 if(storageIssue)return notify("Invalid data is protected. Export the raw data and restore a valid JSON backup.");
 if(!confirm("ERASE ALL LOCAL DATA on this browser? Export a backup first. One local recovery copy will be kept if space allows."))return;
 if(prompt("Type DELETE to confirm")!=="DELETE")return;
 if(!saveRecovery("before reset"))return;
 try{const empty=blank();localStorage.setItem(KEY,JSON.stringify(empty));data=empty;writeFailed=false;recordSaveMeta('lastSavedAt');setPage("dashboard");notify("Workspace reset. Previous records are available under Settings while browser storage remains.")}catch(e){console.error(e);notify("Reset failed; current records were not erased.")}
}
function backupStatusPanel(){
 const copy=getRecovery(),c=snapshotCounts(data);
 return '<section class="card settings-card backup-health" id="backup-health"><h3>◈ Backup Safety & Recovery</h3>'+(storageIssue?'<p class="note warn">⚠ Stored data could not be loaded. Saving is blocked to protect the original data. Download raw data, then restore a valid JSON backup. Reset is disabled.</p><button class="btn btn-danger" data-act="export-raw">Download damaged raw data</button>':'<p class="small muted">Current records: '+c.tasks+' tasks · '+c.money+' money entries · '+c.bills+' bills · '+c.savingsGoals+' savings goals.</p>')+'<p class="small muted">'+(copy?"Latest local recovery: "+esc(new Date(copy.createdAt).toLocaleString("en-PH"))+" ("+esc(copy.reason)+").":"No local recovery copy yet. A copy is made before restoring a backup or resetting your workspace.")+'</p><button class="btn btn-small" data-act="recover-previous" '+(!copy||storageIssue?"disabled":"")+'>Restore previous local records</button><p class="small muted">Local recovery is stored in the same browser as your app. Clearing app storage removes both current data and recovery. Export a separate JSON file regularly.</p></section>';
}
function downloadBackup(){
 if(storageIssue)return downloadDamaged();
 const payload={...data,exportedAt:new Date().toISOString(),release:"1.6",recordCounts:snapshotCounts(data)};
 downloadText("ENAL-OS-backup-"+localDate()+".json",JSON.stringify(payload,null,2),"application/json;charset=utf-8");recordSaveMeta('lastBackupRequestedAt');renderSaveStatus();
 notify("JSON backup download requested. Confirm the file was saved securely.");
}
async function restoreBackup(file){
 if(!file)return;
 if(file.size>5*1024*1024)return notify("Backup file is too large (limit 5 MB).");
 try{
  const next=validateImport(JSON.parse(await file.text()));
  const totals=snapshotCounts(next),summary=Object.entries(totals).map(([k,v])=>k+": "+v).join("\n");
  if(!confirm("Backup contents preview:\n\n"+summary+"\n\nThese records will REPLACE current data. A local recovery snapshot will be created if current data is valid. Export a separate backup before proceeding. Continue?"))return;
  if(storageIssue){if(!confirm("The current records could not be read correctly. Download the damaged raw data before replacing it. Continue restoring this backup?"))return;}
  else if(!saveRecovery("before import"))return;
  localStorage.setItem(KEY,JSON.stringify(next));data=next;storageIssue=false;writeFailed=false;recordSaveMeta('lastSavedAt');render();
  notify("Backup restored successfully. Recovery copy saved when possible.");
 }catch(e){console.error("Import failed:",e);notify("Restore failed: "+e.message)}
}
// Event delegation keeps behavior working even after the page re-renders.
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,k=el.dataset.id;if(act==='overlay'){if(e.target===el)close();return}if(act==='close')return close();if(act==='nav'){close();return setPage(el.dataset.page)}if(act==='go-calendar')return setPage('calendar');if(act==='quick-add')return quickMenu();if(act==='more')return moreMenu();if(act==='savings-new')return savingsGoalForm();if(act==='edit-savings-goal')return savingsGoalForm(data.savingsGoals.find(x=>x.id===k));if(act==='savings-add'||act==='savings-withdraw'){const g=data.savingsGoals.find(x=>x.id===k);if(!g||g.archived)return;return savingsEntryForm(g,act==='savings-add'?'deposit':'withdraw')}if(act==='savings-archive'){const g=data.savingsGoals.find(x=>x.id===k);if(!g)return;if(!confirm((g.archived?'Restore':'Archive')+' this goal? Its entries will be kept.'))return;g.archived=!g.archived;save();render();return}if(act==='insight-export')return exportInsightCSV();if(act==='insight-period'){insightPeriod=el.dataset.value;return render()}if(act==='routine-new')return routineForm();if(act==='routine-edit')return routineForm(data.routines.find(x=>x.id===k));if(act==='routine-toggle')return routineToggle(k);if(act==='routine-delete'){const r=data.routines.find(x=>x.id===k);if(!r||!confirm('Delete this routine and its check-off history?'))return;data.routines=data.routines.filter(x=>x.id!==k);data.routineChecks=data.routineChecks.filter(x=>x.routineId!==k);if(!save())return;close();render();return}if(act==='new-task')return taskForm();if(act==='new-priority')return taskForm({title:'',notes:'',due:localDate(),priority:'high',project:'personal',repeat:'none'});if(act==='new-transaction')return transactionForm();if(act==='grab-income')return transactionForm({type:'income',amount:'',date:localDate(),category:'Grab',note:''});if(act==='grab-fuel')return transactionForm({type:'expense',amount:'',date:localDate(),category:'Grab Fuel',note:''});if(act==='grab-cost')return transactionForm({type:'expense',amount:'',date:localDate(),category:'Grab expense',note:''});if(act==='edit-grab-goal')return grabGoalForm();if(act==='edit-budget')return budgetSettingsForm();if(act==='open-budget')return setPage('finance');if(act==='new-bill')return billForm();if(act==='new-idea')return ideaForm();if(act==='new-project')return projectForm();if(act==='edit-strategy')return strategyForm();if(act==='edit-goal')return goalForm();if(act==='edit-task')return taskForm(data.tasks.find(x=>x.id===k));if(act==='edit-transaction')return transactionForm(data.transactions.find(x=>x.id===k));if(act==='edit-bill')return billForm(data.bills.find(x=>x.id===k));if(act==='edit-idea')return ideaForm(data.ideas.find(x=>x.id===k));if(act==='edit-project')return projectForm(data.projectItems.find(x=>x.id===k));if(act==='toggle-task')return toggleTask(data.tasks.find(x=>x.id===k));if(act==='pay-bill')return payBill(data.bills.find(x=>x.id===k));if(act==='undo-bill')return undoBill(data.billPayments.find(x=>x.id===k));if(act==='delete-task')return removeFrom('tasks',k,'task');if(act==='delete-transaction')return removeFrom('transactions',k,'money record');if(act==='delete-bill')return removeFrom('bills',k,'bill');if(act==='delete-idea')return removeFrom('ideas',k,'idea');if(act==='delete-project')return removeFrom('projectItems',k,'milestone');if(act==='task-filter'){taskFilter=el.dataset.value;return render()}if(act==='idea-filter'){ideaFilter=el.dataset.value;return render()}if(act==='project-filter'){projectFilter=el.dataset.value;return render()}if(act==='idea-task'){const idea=data.ideas.find(x=>x.id===k);data.tasks.push({id:id(),title:idea.title,notes:idea.details,due:localDate(),priority:'medium',project:idea.category==='Velora'?'velora':'personal',repeat:'none',status:'todo',createdAt:new Date().toISOString()});idea.status='actioned';save();setPage('tasks');return notify('Idea converted to a task ✓')}if(act==='cal-day'){selectedCalDate=el.dataset.date;return render()}if(act==='cal-today'){selectedCalDate=localDate();calMonth=selectedCalDate.slice(0,7);return render()}if(act==='cal-prev'||act==='cal-next'){const [y,m]=calMonth.split('-').map(Number);const d=new Date(y,m-1+(act==='cal-prev'?-1:1),1);calMonth=`${d.getFullYear()}-${pad(d.getMonth()+1)}`;selectedCalDate=`${calMonth}-01`;return render()}if(act==='export')return downloadBackup();if(act==='export-raw')return downloadDamaged();if(act==='recover-previous')return recoverPrevious();if(act==='import')return $('#backup-import')?.click();if(act==='reset')return resetWorkspace();});
document.addEventListener('submit',e=>{if(e.target.id==='entity-form'){e.preventDefault();formSave(e.target)}if(e.target.id==='profile-form'){e.preventDefault();const fd=new FormData(e.target);data.settings.name=String(fd.get('name')||'Boss').trim().slice(0,50)||'Boss';data.settings.monthlyGoal=Math.max(0,Number(fd.get('monthlyGoal'))||0);data.settings.dailyGrabGoal=Math.max(0,Number(fd.get('dailyGrabGoal'))||0);save();render();notify('Profile saved ✓')}});
document.addEventListener('change',e=>{if(e.target.id==='transaction-filter'){transactionFilter=e.target.value;render()}if(e.target.id==='backup-import'){restoreBackup(e.target.files?.[0]);e.target.value=''}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){const query=e.target.value.trim().toLowerCase();$('#task-results')?.querySelectorAll('.row-item').forEach(row=>{row.style.display=row.textContent.toLowerCase().includes(query)?'':'none'})}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
window.addEventListener('hashchange',()=>{const incoming=location.hash.slice(1);if(NAV.some(([k])=>k===incoming)&&incoming!==page){page=incoming;render()}});
$('#mobile-capture').dataset.act='quick-add';$('#quick-add').dataset.act='quick-add';$('#more-button').dataset.act='more';
render();
